const ids=["databases", "oltp-olap", "oltp", "why-warehouse", "warehouse", "pipelines", "lakehouse", "medallion", "modeling", "scd", "quality", "engineers", "business", "glossary"];
const data={"en": {"contents": "THE FIELD GUIDE", "draft": "Working draft · v0.2", "aside": "From a single order to a business decision. No technical background needed.", "chapter": "Chapter", "read": "MIN READ", "example": "ONE EXAMPLE, ALL THE WAY THROUGH", "previous": "Previous", "next": "Up next", "sources": "Explore further", "titles": ["What is a database?", "Two jobs for data", "Inside an application", "Why a separate warehouse?", "Meet the data warehouse", "From source to insight", "What is a lakehouse?", "Medallion Architecture", "Analytical schemas · Star & more", "Slowly Changing Dimensions", "Data quality & reliable operation", "What data engineers do", "Why it matters", "Glossary & sources"], "pages": [["Every order starts<br>with <em>a little data.</em>", "How does application data become a reliable report, and what do data engineers do along the way? Follow one online store, from a shoe purchase to a business decision. No technical background needed.", "database", [["A database is an organized memory", "A database stores information so software can find and change it reliably. A database management system is the software that manages that information. In a relational database, information is organized into tables: rows describe individual records, and columns describe their attributes."], ["One purchase, several connected records", "A customer places an order. The order contains a product and a quantity. A payment records whether money was received. Identifiers connect these records without copying every detail into every table."], ["Why not just a spreadsheet?", "Spreadsheets are useful tools. An application also needs to handle many people reading and changing data at the same time, enforce rules and control access. Database systems provide mechanisms for these jobs."]], ["Keep this distinction", "A database is where data is managed. An application is the software that uses it. A data engineer helps make data from these systems useful beyond the original operation."]], ["Same data.<br><em>Different questions.</em>", "“Did my payment succeed?” and “How did sales change this year?” both use data. They require very different kinds of work.", "compare", [["Online Transaction Processing (OLTP)", "OLTP supports everyday operations: placing an order, recording a payment or changing an address. It typically handles many short transactions involving relatively few records."], ["Online Analytical Processing (OLAP)", "OLAP supports analysis: summarizing sales, comparing regions and exploring trends. Queries often read many records and group them into useful measures."], ["A way to describe workloads", "These terms describe how systems process data. They are not a complete taxonomy of databases. Some systems support both transactional and analytical workloads."]], ["Our focus from here", "We will briefly look at application databases, then spend most of this guide on analytical systems, data warehouses and the engineers who build them."]], ["The database behind<br><em>“Place order”.</em>", "An application database helps the store respond to each customer and keep its operations consistent.", "transaction", [["A transaction keeps related changes together", "Imagine that the store reserves stock and creates an order. A database transaction can group these database changes so they succeed or fail together. An external payment service requires additional coordination; it is not automatically part of that transaction."], ["Small operations, many times", "The store looks up one customer, reads one order or changes a small number of records. Many users may do these things concurrently. Fast responses and correct updates matter."], ["Structure follows the application", "Relational application databases often split information into related tables to reduce unnecessary duplication. This is called normalization. It is a common design choice, not a universal rule for every transactional system."]], ["Example question", "“What is the current status of order #1042?” The application needs a specific, up-to-date answer."]], ["An application runs the store.<br><em>What explains the business?</em>", "A sales report may need years of orders, advertising costs, refunds and customer records. That information rarely lives in one place.", "sources", [["Protect the operational workload", "Large analytical queries can compete with customers’ requests for resources. A separate analytical system gives those workloads room to operate independently."], ["Bring different sources together", "The store knows orders. The advertising platform knows campaign costs. The payment provider knows settlements. Combining them makes questions such as “Which campaigns generate profitable sales?” possible."], ["Preserve history and shared meaning", "A product category or customer address can change. Analysis may need to know what was true at the time of a sale. Teams also need an agreed meaning for measures such as revenue and a clear treatment of cancellations and refunds."], ["The bridge: from application to analytics", "The application records orders in its Online Transaction Processing (OLTP) database. An automated data pipeline reads selected records or changes, copies them to a separate data warehouse and prepares them for Online Analytical Processing (OLAP). The application continues to use its own database; analysts query the prepared data in the warehouse. This is a data flow, not two unrelated collections."], ["An overnight job, step by step", "A job is an automated task. In our example, customers place orders throughout Monday. At 02:00 on Tuesday, a scheduled job collects new and changed orders, prepares the analytical tables and checks the results. By 08:00, the report shows Monday’s sales. Updates, cancellations and refunds need to be carried across too; the process does not necessarily copy the entire database every night."], ["How often should it run?", "Nightly batch loading is a common approach when yesterday’s data is fresh enough. Teams may schedule resource-intensive work outside peak hours to reduce competition with application traffic, but a production system is not necessarily idle at night. Other datasets refresh hourly, daily, weekly or monthly, depending on the business need. Some pipelines deliver changes almost continuously. The schedule is a design choice, not a requirement of OLAP."]], ["Separate does not mean instant", "Data is copied and prepared on a schedule or as changes arrive. A report should tell readers how fresh its data is."]], ["A shared home<br>for <em>analytical questions.</em>", "A data warehouse brings data together and organizes it for analysis across the business. Think of it as prepared business memory.", "warehouse", [["Data Warehouse (DWH)", "A data warehouse is an analytical data system that integrates data from different sources. It can hold detailed history as well as summaries. A data mart is a focused collection prepared for a particular subject or team."], ["A different pattern of work", "An application might fetch one order. A warehouse might scan millions of order lines to calculate monthly sales by category. Analytical designs are optimized around those access patterns."], ["Warehouse and OLAP are related ideas", "Online Analytical Processing (OLAP) describes analytical processing. A data warehouse is a system used to organize and serve analytical data. OLAP does not require a literal cube, and a warehouse is more than a collection of dashboards."], ["Why analytical engines can scan so much data", "Column-oriented storage groups values from the same column together. A sales total may need only the date and amount columns, not every field of each order. Compression reduces the data to read, and parallel processing splits work across compute resources. These are common analytical techniques, not a definition of every analytical database."]], ["What comes next", "First we will follow the pipeline that delivers and prepares data. Then we will compare warehouse and lakehouse approaches and explore layers and analytical models."]], ["A reliable route<br>from <em>source to insight.</em>", "A data pipeline is a sequence of steps that moves and prepares data. Its job is to make the right information available at the right time.", "pipeline", [["Extract, Transform, Load (ETL)", "Read data from a source, transform it, then load it into the destination. Extract, Load, Transform (ELT) changes the order: load first, then transform using the destination’s processing capabilities."], ["What transformations actually do", "Deduplication removes repeated deliveries of the same record. Standardization makes dates, statuses and units consistent. A join connects related records using keys, such as an order and its payment. Aggregation groups detail into measures, such as daily sales. Each step must preserve the meaning and level of detail required by the business."], ["A little at a time", "A full load copies everything in scope. An incremental load processes new or changed data. Change Data Capture (CDC) identifies changes in the source, often through its transaction log. Each approach needs a way to handle updates and deletions."], ["Coordinate and recover", "Orchestration controls schedules, dependencies and retries. A repeatable pipeline should avoid creating duplicates when a step runs again, and allow historical periods to be reprocessed when logic changes."], ["Batch and streaming", "Batch processes groups of records periodically. Streaming processes events continuously or in small increments. Choose based on the freshness the business needs and the complexity it can support."], ["Next: where that pipeline runs", "The same delivery and transformation concepts apply across analytical platforms. Next we will look at a lakehouse, then organize the preparation steps into Bronze, Silver and Gold layers."]], ["A visible promise", "“Yesterday’s sales will be ready by 08:00” is a requirement people can understand and the engineering team can monitor."]], ["A lake’s flexibility.<br><em>A warehouse’s discipline.</em>", "A data lakehouse combines file-based storage with managed tables and analytical processing. It brings ideas from data lakes and data warehouses into one architecture.", "lakehouse", [["Three related approaches", "A data warehouse organizes data into tables and models for analytics and reporting. A data lake stores varied data as files, often in object storage: orders, events, logs and documents. A lakehouse adds managed tables and analytical capabilities over lake storage. Modern products overlap; these are architectural ideas rather than rigid product categories. Object storage keeps files as named objects, rather than managing them as rows of a database table."], ["Files become managed tables", "A folder of files alone does not tell readers which files form the current table or what to read while a writer is updating it. A table format adds metadata that tracks table contents and versions, enabling consistent reads and reliable updates. Delta Lake and Apache Iceberg are examples of table formats used for this purpose."], ["The platform needs more than storage", "A catalog helps users discover tables and manage access. Processing engines read and transform the data and answer queries. Together, storage, table management, a catalog and compute form the analytical platform. A lakehouse is an architecture, not a single database product."], ["Our store, on a lakehouse", "Orders and website events arrive as files. Managed tables hold cleaned order lines and browsing events. Analysts query prepared sales tables, while a data scientist can use related data to study buying behavior. Sharing the foundation can reduce unnecessary copying; it does not mean that every dataset exists in only one physical copy."], ["How this relates to Medallion Architecture", "Lakehouse describes the platform’s storage and processing approach. Medallion Architecture describes how datasets are organized by preparation stage: Bronze, Silver and Gold. They fit together well, but either concept can be understood independently. The next chapter explains those layers."]], ["Two questions to keep separate", "“Where and how is data managed?” points to the platform architecture. “How is raw data turned into business-ready data?” points to the layers and transformations."]], ["From raw records<br>to <em>business-ready data.</em>", "Medallion Architecture is a widely used layered design pattern, especially in lakehouses. Its Bronze, Silver and Gold layers also provide a useful way to organize analytical warehouses.", "medallion", [["One architecture, three responsibilities", "It describes how data is organized and progressively refined, rather than infrastructure to install. Bronze preserves source input, Silver creates reusable validated data, and Gold prepares datasets for a business purpose. It is one common pattern, not a requirement for every warehouse."], ["Bronze · keep what arrived", "Land data close to its source form, with minimal transformation and metadata such as ingestion time and source. For our store, this means incoming order records, including repeated deliveries and unexpected values. Retaining the input supports investigation and reprocessing, subject to retention and access policies."], ["Silver · clean and connect", "Apply data types, deduplicate records, validate identifiers and handle changes consistently. Join related sources where appropriate. Invalid records can be set aside for investigation rather than silently disappearing. Our store now has reliable order lines, payments and refunds at a clearly defined level of detail."], ["Gold · serve a business question", "Publish consumption-ready models and measures with agreed definitions. Examples include sales fact tables, product dimensions and a daily net-sales summary by category. Gold may contain detailed dimensional models as well as aggregates; it is not limited to dashboards or summary tables."], ["Follow one order through the layers", "Bronze retains two deliveries of order #1042. Silver recognizes the shared order key, applies the correct update rules and keeps a consistent representation. Gold uses that order once in the relevant sales measure and applies the agreed refund rules. These are illustrative rules; the project must define its own keys and business logic."], ["Layers are logical boundaries", "Bronze, Silver and Gold can be schemas, groups of tables or separate storage areas. They do not require three physical databases. Both overnight batch jobs and continuous processing can move data through these layers. Each boundary needs explicit quality checks, ownership and freshness expectations."], ["Why engineers use this separation", "When a transformation is wrong, retained source input can help rebuild downstream tables without requesting another source extract, provided the necessary history remains available. Shared Silver datasets reduce repeated cleanup, while Gold keeps business-specific calculations explicit. In the next chapter, we will look at analytical schemas and the facts and dimensions often used in Gold."]], ["A map for understanding a project", "Ask: where do raw records land, where are they validated, and where are business-ready datasets published? Layer names alone do not guarantee quality; the rules and checks do."]], ["Different shapes.<br><em>One business question.</em>", "Analytical models organize events and their context in different ways. Start with the main patterns, then focus on Star Schema: a widely used starting point for business-facing reporting.", "star", [["Facts and dimensions, first", "A fact table records events or observations. In our store, one row represents one order line; quantity and line amount are measures. This level of detail is the grain. Dimension tables describe the context: the product, customer and date. Their keys connect facts to descriptive attributes. One order with three items produces three order-line rows, but it is still one order. Counting rows answers a different question from counting distinct order identifiers."], ["A map of the main patterns", "There is no single exhaustive list of analytical schemas. Star and Snowflake describe dimensional layouts; Fact Constellation extends them across several business processes. A wide table is another way to serve analytics. These choices can coexist in one platform."], ["Focus · Star Schema", "Put a fact table at the center and connect dimension tables directly to it. Product category and brand can sit alongside the product name in one product dimension. One dimension row can describe many fact rows. This makes grouping and filtering approachable and keeps common query paths short."], ["Why use Star as the starting point?", "For a business-facing dimensional model, Star is a well-established default: readers can find measures in facts and descriptive filters in dimensions. It is especially useful for reporting and self-service analysis. It is not guaranteed to be the fastest layout on every engine; test actual workloads and consider platform guidance."], ["Snowflake Schema · split dimension hierarchies", "Normalize part of a dimension into additional related tables. For example, Sales connects to Product, Product connects to Subcategory, and Subcategory connects to Category. This reduces repetition of hierarchy attributes but adds tables and joins. It can be useful when normalized hierarchies need independent management. This schema name is unrelated to choosing the Snowflake software platform."], ["Fact Constellation · several facts, shared context", "Also called a galaxy schema, this layout uses multiple fact tables that share conformed dimensions: dimensions with consistent definitions and meaning. Sales and returns can share Product, Customer and Date, while keeping each fact table at its own grain. Aggregate each fact separately to the required common level before combining results; joining raw facts directly can multiply rows."], ["Wide table · put frequently used attributes together", "A denormalized table repeats descriptive fields alongside event measures to reduce joins. It can simplify a targeted workload, but duplicates attributes and can complicate updates and reuse. Some engines also support nested and repeated structures. The best physical representation depends on the platform and workload."], ["Other approaches belong on the wider map", "Normalized enterprise models and Data Vault are other ways to organize warehouse integration and history. They are not simply more variants of Star Schema, and may feed dimensional reporting models. This introduction focuses on the structures a report reader is most likely to encounter."], ["Not every number can be summed", "Revenue in a common currency can usually be summed across sales. Adding daily stock balances across days does not give a meaningful total stock. A discount percentage is not summed either: the aggregation rule must match the business question. Define the grain, currency and measure rules before building the report."], ["Structure and history are separate choices", "Star versus Snowflake describes how tables relate. Slowly Changing Dimensions (SCD) describes how dimension attributes change over time. A Star Schema can use Type 1 or Type 2 dimensions. Next, we will see how a customer’s move affects historical reporting."]], ["A practical starting point", "For a new business-facing reporting model, start by considering Star Schema. Define the grain and business measures first; choose a different layout when its benefits justify the added tradeoffs."]], ["When a customer moves,<br><em>what happens to history?</em>", "Slowly Changing Dimensions (SCD) are techniques for handling changes to descriptive attributes over time. Types 1 and 2 are common foundations; Type 6 is a more specialized hybrid.", "scd", [["First, what is a dimension?", "A dimension describes an entity, such as a customer, product or store. A fact records an event, such as a sale. Suppose customer C208 moves from Warsaw to Kraków on 1 October 2026. Should September sales still belong to Warsaw, or should all sales now appear under Kraków? The reporting requirement determines how we store the change."], ["Type 1 · overwrite the value", "Replace Warsaw with Kraków in the existing customer row. This attribute’s previous value is not retained in that dimension. Type 1 is simple and appropriate when only the latest value matters, or when correcting an error that should not be treated as a historical change."], ["Type 2 · add a new version", "Keep the old customer version and insert a new one. The business key, customer_id, still identifies C208. A surrogate key, customer_sk, uniquely identifies each version. valid_from and valid_to define its effective interval; is_current makes the latest version easy to find. This is the main history-preserving approach explored here, not a universal best choice for every attribute."], ["Read the extra columns", "Version 501 describes C208 in Warsaw before 1 October. Version 734 describes the same customer in Kraków from that date. In this example valid_from is inclusive and valid_to is exclusive: an event on 1 October belongs only to version 734. NULL means that the current interval has no known end. Real systems can use timestamps rather than dates."], ["Attach facts to the correct version", "When loading a sale, resolve the customer version effective at the sale’s business time and store its surrogate key on the sales fact. A September sale references 501; an October sale references 734. Joining through that key preserves the location that applied when each sale happened. Joining only on customer_id can match multiple versions and double-count facts."], ["What should we choose?", "Use Type 1 when history is unnecessary, Type 2 when reporting must reflect what was true at the time, and Type 6 when both historical and current classifications are explicitly needed. A single dimension can use different strategies for different attributes. Types 0, 3 and other variants also exist; these three are the focus of this introduction."], ["Type 6 · history plus a current-value view", "In the Kimball definition used here, Type 6 adds Type 1 attributes to a Type 2 dimension. Keep the historical city on each version, and also store current_city. After the move, current_city becomes Kraków on every version of C208. Reports can then group sales by either the historical city or the current city. This offers flexibility but adds update logic and storage; it is not automatically better than Type 2."], ["Implementation checks that matter", "For each entity, prevent overlapping effective intervals and unintended duplicate current versions. Close the previous interval and create the new version consistently, and make retries safe. Late-arriving corrections need explicit rules. Periodic snapshots only observe states available at capture time: they cannot reconstruct every change that happened between runs."], ["How this fits the layers", "History can be captured and standardized in Silver, while business-facing dimensions can be published in Gold. The exact placement depends on the project. Medallion Architecture organizes preparation stages; Slowly Changing Dimensions organize changes over time. Next we will check whether the resulting data is complete, fresh and safe to publish."]], ["A practical default for historical reporting", "Start by asking whether an attribute’s past values matter. Type 2 is a strong starting point when they do; Type 1 remains useful when only the latest value is required."]], ["A finished job.<br><em>A trustworthy report?</em>", "A successful task means its code finished. It does not automatically mean that every expected record arrived or that the report is ready for business use.", "quality", [["Four questions before publication", "Completeness: did all expected records arrive? Uniqueness: did retries create duplicates? Referential integrity: do order records point to valid customers and products? Freshness: what business period is available, and when was it last updated? Checks should use explicit rules rather than a vague “data looks fine.”"], ["Reconcile with the source", "Compare source and destination counts and relevant totals for the same period, scope and cutoff time. A difference may reveal a missed batch, a filter or a known transformation. Matching counts alone do not prove correctness, so combine checks and investigate unexpected differences."], ["When a dependency fails", "Suppose orders loaded but payments did not. A report that requires both should not be marked ready simply because the orders task succeeded. Orchestration tracks dependencies, records the failure and alerts the responsible team. Where appropriate, keep the last validated report available with a clear freshness warning."], ["Recover without counting twice", "Fix the cause and rerun the affected steps. Idempotency means that repeating the same operation produces the same intended result instead of adding duplicates. A backfill reprocesses a historical period, for example after correcting a calculation. Validate the repaired output before publishing it."], ["Meaning, ownership and access", "A dataset needs an owner, documented definitions and suitable access. Data lineage shows where data originated and which transformations produced it. Record business event time separately from ingestion time where needed: a sale can arrive late, and “loaded today” does not mean “sold today.”"], ["What readers should see", "State the covered period and last successful refresh. Make missing or stale data visible. A trustworthy system helps people know when an answer is ready and when they need to wait. Next we will connect these responsibilities to the work of data engineers."]], ["A useful promise", "“Yesterday’s complete sales are validated and ready by 08:00.” Monitor both the arrival deadline and the quality checks behind that promise."]], ["The work behind<br><em>trustworthy data.</em>", "Data engineers build and operate the systems that turn scattered source data into dependable datasets for other people and applications.", "engineer", [["Connect and prepare", "Understand source systems, arrange appropriate access, build ingestion and implement transformations. Model useful datasets together with the people who know the business."], ["Make quality observable", "Check for missing records, unexpected duplicates, invalid values and late arrivals. Monitor freshness and failures. Document where data came from and how it changed; that history is called data lineage."], ["Operate the system", "Investigate incidents, recover missed data, adapt to source changes and improve performance. Manage access and costs so the system stays useful as it grows."], ["Example: an order arrives twice", "A retry delivers the same order again. The engineer designs a stable record key and repeatable loading logic, checks uniqueness and investigates the cause. The goal is to prevent a retry from doubling reported sales."]], ["The deliverable is more than code", "A useful dataset needs clear meaning, an owner, expected freshness and a practical way to notice and fix problems."]], ["Better decisions start<br>with <em>dependable foundations.</em>", "The outcome is not simply that data moved. It is that people can use it, understand it and know when it is ready.", "business", [["One question, a complete journey", "The manager asks which product categories grew last quarter. Orders and refunds are collected, product classifications are applied, agreed revenue rules are calculated, and a report presents the result with its update time."], ["Work shared across roles", "Application developers build the store’s operational behavior. Data engineers build and run the data flow and analytical foundations. Analysts investigate questions and communicate findings. In practice, responsibilities overlap and vary between teams."], ["What success looks like", "Reports arrive when promised. Numbers have documented definitions. Access matches people’s responsibilities. When something fails, the team notices and can recover. These qualities make analysis useful for decisions."]], ["The central idea", "Data engineers make the journey from operational records to useful, reliable data repeatable."]], ["A few terms.<br><em>A clearer conversation.</em>", "A reference to return to whenever an unfamiliar abbreviation gets in the way.", "glossary", [], null]]}, "ru": {"contents": "ОГЛАВЛЕНИЕ", "draft": "Рабочий черновик · v0.2", "aside": "От одного заказа до решения бизнеса. Без технической подготовки.", "chapter": "Глава", "read": "МИН ЧТЕНИЯ", "example": "ОДИН ПРИМЕР ЧЕРЕЗ ВЕСЬ РАССКАЗ", "previous": "Назад", "next": "Далее", "sources": "Подробнее", "titles": ["Что такое база данных?", "Две задачи для данных", "Внутри приложения", "Зачем отдельное хранилище?", "Знакомство с хранилищем", "От источника к результату", "Что такое lakehouse?", "Медальонная архитектура", "Аналитические схемы", "Изменения измерений (SCD)", "Качество и надёжная работа", "Работа дата-инженера", "Польза для бизнеса", "Глоссарий и источники"], "pages": [["Каждый заказ начинается<br><em>с данных.</em>", "Как данные приложения становятся надёжным отчётом и что на этом пути делают дата-инженеры? Проследим работу интернет-магазина: от покупки кроссовок до решения бизнеса. Техническая подготовка не нужна.", "database", [["База данных — организованная память", "База данных хранит информацию так, чтобы программы могли находить и надёжно изменять её. Система управления базами данных — программа, которая этим управляет. В реляционной базе информация организована в таблицы: строки описывают отдельные записи, столбцы — их свойства."], ["Одна покупка, несколько связанных записей", "Покупатель оформляет заказ. В заказе есть товар и количество. Платёж показывает, получены ли деньги. Идентификаторы связывают записи, позволяя не копировать все подробности в каждую таблицу."], ["Почему не просто электронная таблица?", "Электронные таблицы полезны. Но приложению также нужно одновременно обслуживать множество пользователей, соблюдать правила изменения данных и ограничивать доступ. Системы баз данных предоставляют механизмы для этих задач."]], ["Разделим понятия", "База данных управляет информацией. Приложение использует её. Дата-инженер помогает сделать данные этих систем полезными за пределами исходной операции."]], ["Одни данные.<br><em>Разные вопросы.</em>", "«Прошла ли моя оплата?» и «Как изменились продажи за год?» — оба вопроса требуют данных, но очень разной обработки.", "compare", [["Online Transaction Processing (OLTP) — оперативная обработка транзакций", "OLTP обслуживает текущие операции: оформление заказа, запись платежа, изменение адреса. Обычно это множество коротких транзакций, затрагивающих небольшое число записей."], ["Online Analytical Processing (OLAP) — аналитическая обработка данных", "OLAP помогает анализировать данные: суммировать продажи, сравнивать регионы, изучать тенденции. Запросы часто читают много записей и группируют их в полезные показатели."], ["Это характеристика нагрузки", "Термины описывают способы обработки данных, а не исчерпывающую классификацию баз. Некоторые системы поддерживают и транзакционные, и аналитические нагрузки."]], ["Наш дальнейший фокус", "Коротко рассмотрим базы приложений, затем сосредоточимся на аналитике, хранилищах данных и работе инженеров."]], ["Что стоит за кнопкой<br><em>«Оформить заказ».</em>", "База приложения помогает магазину отвечать покупателям и сохранять согласованность операций.", "transaction", [["Транзакция объединяет связанные изменения", "Например, магазин резервирует товар и создаёт заказ. Транзакция базы данных может объединить эти изменения: они выполняются или отменяются вместе. Внешний платёжный сервис требует отдельной координации и автоматически в эту транзакцию не входит."], ["Небольшие операции, много раз", "Магазин находит покупателя, читает заказ или изменяет несколько записей. Множество пользователей могут делать это одновременно. Важны быстрые ответы и корректные изменения."], ["Структура следует потребностям приложения", "В реляционных базах приложений данные часто разделяют на связанные таблицы, чтобы уменьшить лишнее дублирование. Это называется нормализацией. Это распространённый приём, а не обязательное правило для всех транзакционных систем."]], ["Пример вопроса", "«Каков текущий статус заказа №1042?» Приложению нужен конкретный актуальный ответ."]], ["Приложение обслуживает магазин.<br><em>А что объясняет бизнес?</em>", "Отчёту могут понадобиться заказы за несколько лет, расходы на рекламу, возвраты и данные покупателей. Обычно они находятся в разных местах.", "sources", [["Разделить нагрузки", "Тяжёлые аналитические запросы могут конкурировать за ресурсы с запросами покупателей. Отдельная аналитическая система позволяет этим нагрузкам работать независимо."], ["Соединить разные источники", "Магазин знает заказы, рекламная платформа — затраты на кампании, платёжный сервис — расчёты. Вместе эти данные помогают ответить, какая реклама приносит прибыльные продажи."], ["Сохранить историю и общий смысл", "Категория товара или адрес покупателя могут измениться. Анализу бывает важно, что было верно на момент продажи. Командам также нужны общие определения выручки и правила учёта отмен и возвратов."], ["Связующее звено: от приложения к аналитике", "Приложение записывает заказы в базу Online Transaction Processing (OLTP) — оперативной обработки транзакций. Автоматический пайплайн читает выбранные записи или изменения, копирует их в отдельное хранилище и подготавливает для Online Analytical Processing (OLAP) — аналитической обработки данных. Приложение продолжает работать со своей базой, а аналитики запрашивают подготовленные данные хранилища. Это связанный поток данных, а не две независимые коллекции."], ["Ночная загрузка по шагам", "Job, или задача, — автоматически выполняемая работа. В нашем примере покупатели оформляют заказы в понедельник. Во вторник в 02:00 задача по расписанию собирает новые и изменённые заказы, подготавливает аналитические таблицы и проверяет результат. К 08:00 отчёт показывает продажи понедельника. Обновления, отмены и возвраты тоже нужно переносить; копировать всю базу каждую ночь необязательно."], ["Как часто обновлять данные?", "Ночная пакетная загрузка — распространённый вариант, когда достаточно данных за вчера. Ресурсоёмкую работу могут планировать вне пиковых часов, чтобы меньше конкурировать с приложением, но production-система не обязательно простаивает ночью. Другие наборы обновляются каждый час, день, неделю или месяц — в зависимости от задачи бизнеса. Некоторые пайплайны передают изменения почти непрерывно. Расписание — выбор архитектуры, а не требование OLAP."]], ["Отдельно — не значит мгновенно", "Данные копируются и подготавливаются по расписанию или по мере поступления изменений. Отчёт должен показывать, насколько свежие в нём данные."]], ["Общий дом<br><em>для аналитических вопросов.</em>", "Хранилище объединяет данные и организует их для анализа всего бизнеса. Это подготовленная память компании.", "warehouse", [["Data Warehouse (DWH) — хранилище данных", "Хранилище — аналитическая система, объединяющая данные разных источников. В ней могут быть подробная история и агрегаты. Data mart, или витрина данных, — набор, подготовленный для конкретной темы или команды."], ["Другой характер работы", "Приложение может запросить один заказ. Хранилище — прочитать миллионы строк заказов для расчёта продаж по месяцам и категориям. Аналитические решения оптимизируют под такие запросы."], ["Хранилище и OLAP связаны, но различаются", "Online Analytical Processing (OLAP) — аналитическая обработка данных. Хранилище — система их организации и предоставления. OLAP не требует буквального куба, а хранилище не сводится к набору дашбордов."], ["Как аналитические движки читают большие объёмы", "Колоночное хранение группирует значения одного столбца. Для суммы продаж могут понадобиться только дата и сумма, а не все поля заказа. Сжатие уменьшает объём чтения, а параллельная обработка распределяет работу между вычислительными ресурсами. Это распространённые аналитические приёмы, а не определение любой аналитической базы."]], ["Что дальше", "Сначала проследим пайплайн доставки и подготовки данных. Затем сравним хранилище и lakehouse, разберём слои и аналитические модели."]], ["Надёжный путь<br><em>от источника до отчёта.</em>", "Пайплайн данных — последовательность шагов перемещения и подготовки данных. Его задача — доставить нужную информацию вовремя.", "pipeline", [["Extract, Transform, Load (ETL) — извлечь, преобразовать, загрузить", "Данные читают из источника, преобразуют и загружают в целевую систему. Extract, Load, Transform (ELT) меняет порядок: сначала загрузка, затем преобразование средствами целевой системы."], ["Что именно делают преобразования", "Дедупликация устраняет повторные доставки одной записи. Стандартизация приводит даты, статусы и единицы к общему виду. Join — соединение — связывает записи по ключам, например заказ и платёж. Aggregation — агрегирование — обобщает подробные записи в показатели, например продажи за день. Каждый шаг должен сохранять нужные бизнесу смысл и детализацию."], ["Необязательно копировать всё", "Полная загрузка копирует весь нужный набор. Инкрементальная обрабатывает новые или изменённые данные. Change Data Capture (CDC) — отслеживание изменений в источнике, часто через журнал транзакций. Нужно учитывать также обновления и удаления."], ["Координация и восстановление", "Оркестрация управляет расписанием, зависимостями и повторными запусками. Повторяемый процесс не должен создавать дубликаты при перезапуске и должен позволять пересчитать прошлые периоды после изменения логики."], ["Пакетная и потоковая обработка", "Пакетная обработка запускается для групп записей периодически. Потоковая обрабатывает события непрерывно или небольшими порциями. Выбор зависит от нужной свежести и допустимой сложности."], ["Далее: где работает пайплайн", "Доставка и преобразования нужны на разных аналитических платформах. Далее рассмотрим lakehouse, а затем организуем подготовку данных по слоям Bronze, Silver и Gold."]], ["Понятное обещание", "«Вчерашние продажи будут готовы к 08:00» — требование, понятное бизнесу и доступное для мониторинга инженерам."]], ["Гибкость озера.<br><em>Порядок хранилища.</em>", "Data lakehouse сочетает файловое хранение с управляемыми таблицами и аналитической обработкой. Эта архитектура объединяет идеи озера данных и аналитического хранилища.", "lakehouse", [["Три связанных подхода", "Data warehouse — хранилище данных — организует данные в таблицы и модели для аналитики и отчётности. Data lake — озеро данных — хранит разнообразные данные в файлах, часто в объектном хранилище: заказы, события, логи и документы. Lakehouse добавляет управление таблицами и аналитические возможности поверх хранения озера. Современные продукты пересекаются по возможностям: это архитектурные идеи, а не жёсткие категории продуктов. Объектное хранилище сохраняет файлы как именованные объекты, а не управляет ими как строками таблицы базы данных."], ["Файлы становятся управляемыми таблицами", "Одна папка с файлами не объясняет, какие файлы составляют актуальную таблицу и что читать во время обновления. Табличный формат добавляет метаданные о составе и версиях таблицы, позволяя согласованно читать данные и надёжно применять изменения. Примеры таких форматов — Delta Lake и Apache Iceberg."], ["Платформа — не только хранение", "Каталог помогает находить таблицы и управлять доступом. Вычислительные движки читают и преобразуют данные, выполняют запросы. Вместе хранение, управление таблицами, каталог и вычисления образуют аналитическую платформу. Lakehouse — архитектура, а не один конкретный продукт базы данных."], ["Наш магазин на lakehouse", "Заказы и события сайта поступают в виде файлов. Управляемые таблицы содержат очищенные позиции заказов и события просмотра. Аналитики запрашивают подготовленные продажи, а специалист по данным может изучать поведение покупателей на связанных данных. Общая основа уменьшает лишнее копирование, но не означает, что у каждого набора существует лишь одна физическая копия."], ["Связь с Medallion Architecture", "Lakehouse описывает подход к хранению и обработке данных на платформе. Medallion Architecture описывает организацию наборов по степени подготовки: Bronze, Silver и Gold. Эти идеи хорошо сочетаются, но каждую можно понимать отдельно. Следующая глава объясняет слои."]], ["Два разных вопроса", "«Где и как управляют данными?» — вопрос об архитектуре платформы. «Как исходные записи становятся данными для бизнеса?» — вопрос о слоях и преобразованиях."]], ["От исходных записей<br><em>к данным для бизнеса.</em>", "Medallion Architecture — распространённый подход к организации данных по слоям, особенно в lakehouse-системах. Слои Bronze, Silver и Gold также помогают организовать аналитическое хранилище.", "medallion", [["Одна архитектура, три ответственности", "Это способ организации и постепенной подготовки данных, а не инфраструктура, которую нужно установить. Bronze сохраняет входные данные, Silver формирует проверенные наборы общего назначения, Gold готовит данные для задач бизнеса. Это распространённый подход, а не обязательное устройство любого хранилища."], ["Bronze · сохранить поступившее", "Данные сохраняют близко к исходному виду, с минимальными преобразованиями и метаданными: временем загрузки и источником. В магазине это входящие записи заказов, включая повторные доставки и неожиданные значения. Исходные записи помогают расследовать ошибки и повторять обработку с учётом правил хранения и доступа."], ["Silver · очистить и связать", "Здесь задают типы данных, устраняют дубликаты, проверяют идентификаторы и согласованно обрабатывают изменения. При необходимости объединяют источники. Некорректные записи можно изолировать для разбора, а не незаметно удалять. В примере магазина получаются надёжные данные о позициях заказов, платежах и возвратах с явно заданной детализацией."], ["Gold · ответить на вопрос бизнеса", "Публикуются готовые к использованию модели и показатели с согласованными определениями: например, факты продаж, измерения товаров и ежедневные продажи за вычетом возвратов по категориям. Gold может содержать подробные модели и агрегаты; это не только дашборды и итоговые таблицы."], ["Один заказ проходит через слои", "Bronze сохраняет две доставки заказа №1042. Silver распознаёт общий ключ, применяет правила обновления и формирует согласованное представление. Gold учитывает заказ один раз в соответствующем показателе и применяет правила возвратов. Это учебный пример: ключи и бизнес-логику нужно определить для конкретного проекта."], ["Слои — логические границы", "Bronze, Silver и Gold могут быть схемами, группами таблиц или отдельными областями хранения. Три физических базы не обязательны. Данные могут проходить слои ночными пакетными заданиями или непрерывно. На каждой границе нужны явные проверки качества, ответственные и ожидания по свежести."], ["Зачем инженерам такое разделение", "Если преобразование ошибочно, сохранённые исходные данные позволяют пересоздать последующие таблицы без новой выгрузки из источника, если нужная история ещё доступна. Общие наборы Silver уменьшают повторную очистку, а Gold делает расчёты бизнеса явными. Далее рассмотрим аналитические схемы, факты и измерения, которые часто используют в Gold."]], ["Карта для знакомства с проектом", "Спросите: куда попадают исходные записи, где их проверяют и где публикуют данные для бизнеса? Названия слоёв сами по себе не гарантируют качество — его обеспечивают правила и проверки."]], ["Разные формы.<br><em>Один вопрос бизнеса.</em>", "Аналитические модели по-разному связывают события с их контекстом. Рассмотрим основные варианты и подробнее — Star Schema, распространённую отправную точку для отчётности бизнеса.", "star", [["Сначала факты и измерения", "Таблица фактов хранит события или наблюдения. В магазине одна строка — одна позиция заказа, количество и сумма позиции — меры. Этот уровень детализации называют grain. Измерения описывают контекст: товар, покупателя и дату. Их ключи связывают факты с описательными атрибутами. Один заказ с тремя товарами даёт три строки позиций, но остаётся одним заказом. Число строк и число уникальных идентификаторов заказов отвечают на разные вопросы."], ["Карта основных вариантов", "Единого исчерпывающего списка аналитических схем нет. Star и Snowflake описывают структуру измерений, Fact Constellation объединяет несколько процессов бизнеса. Широкая таблица — ещё один способ предоставления аналитических данных. На одной платформе эти подходы могут сочетаться."], ["Главный фокус · Star Schema — звезда", "В центре находится таблица фактов, а измерения связаны с ней напрямую. Категория и бренд могут храниться рядом с названием товара в одном измерении товаров. Одной строке измерения соответствует много строк фактов. Так проще выбирать признаки группировки и фильтрации, а пути соединений остаются короткими."], ["Почему начинать со звезды?", "Для модели отчётности бизнеса звезда — устоявшаяся отправная точка: меры ищут в фактах, описательные фильтры — в измерениях. Это удобно для отчётности и самостоятельного анализа. Но звезда не гарантирует максимальную скорость на любом движке: нужно проверять реальные запросы и учитывать рекомендации платформы."], ["Snowflake Schema — снежинка", "Часть измерения нормализуют, выделяя дополнительные связанные таблицы. Например, продажи связаны с товаром, товар — с подкатегорией, подкатегория — с категорией. Повторений атрибутов иерархии меньше, но таблиц и соединений больше. Это полезно, когда нормализованной иерархией нужно управлять отдельно. Название схемы не означает выбор программной платформы Snowflake."], ["Fact Constellation — созвездие фактов", "Также называют galaxy schema. Несколько таблиц фактов используют согласованные измерения с общими определениями и смыслом. Продажи и возвраты могут разделять товары, покупателей и даты, сохраняя свою детализацию. Перед объединением результатов каждый факт агрегируют отдельно до нужного общего уровня: прямое соединение исходных фактов может размножить строки."], ["Широкая таблица · часто нужные атрибуты рядом", "Денормализованная таблица повторяет описательные поля рядом с мерами событий, уменьшая число соединений. Это может упростить конкретную задачу, но дублирует атрибуты и усложняет обновления и повторное использование. Некоторые движки поддерживают вложенные и повторяющиеся структуры. Физическое представление выбирают под платформу и нагрузку."], ["Другие подходы на общей карте", "Нормализованные корпоративные модели и Data Vault — другие способы организации интеграции и истории в хранилище. Это не просто дополнительные варианты звезды; они могут быть источниками для моделей отчётности. Здесь мы сосредоточимся на структурах, которые чаще встречаются читателю отчётов."], ["Не каждое число можно суммировать", "Выручку в общей валюте обычно можно суммировать по продажам. Сумма ежедневных остатков за несколько дней не даёт осмысленного общего остатка. Проценты скидки тоже не суммируют: правило агрегирования должно соответствовать вопросу бизнеса. Детализацию, валюту и правила показателей определяют до построения отчёта."], ["Структура и история — разные решения", "Star и Snowflake описывают связи таблиц. Slowly Changing Dimensions (SCD) — медленно изменяющиеся измерения — описывают учёт изменений атрибутов во времени. Звезда может использовать измерения типов 1 и 2. Далее разберём, как переезд покупателя влияет на историческую отчётность."]], ["Практическая отправная точка", "Для новой модели отчётности бизнеса сначала рассмотрите звезду. Определите детализацию и показатели; выбирайте другую структуру, когда её преимущества оправдывают дополнительные компромиссы."]], ["Покупатель переехал.<br><em>Что будет с историей?</em>", "Slowly Changing Dimensions (SCD) — медленно изменяющиеся измерения — приёмы учёта изменений описательных атрибутов во времени. Типы 1 и 2 — распространённая основа; тип 6 — более специализированный гибрид.", "scd", [["Сначала: что такое измерение?", "Измерение описывает сущность: покупателя, товар или магазин. Факт фиксирует событие, например продажу. Покупатель C208 переезжает из Варшавы в Краков 1 октября 2026 года. Сентябрьские продажи должны остаться в Варшаве или теперь все продажи нужно показывать в Кракове? Требования отчётности определяют способ хранения изменений."], ["Тип 1 · перезаписать значение", "В существующей строке покупателя Варшава заменяется Краковом. Предыдущее значение этого атрибута в измерении не сохраняется. Тип 1 подходит, когда нужно только актуальное значение, или для исправления ошибки, которую не нужно считать историческим изменением."], ["Тип 2 · добавить новую версию", "Старая версия покупателя остаётся, а новая добавляется отдельной строкой. Бизнес-ключ customer_id по-прежнему обозначает C208. Суррогатный ключ customer_sk уникально обозначает версию. valid_from и valid_to задают период действия, is_current помогает найти текущую версию. Здесь это основной способ сохранения истории, но не универсально лучший выбор для любого атрибута."], ["Как читать добавленные колонки", "Версия 501 описывает C208 в Варшаве до 1 октября. Версия 734 — того же покупателя в Кракове начиная с этой даты. В примере начало valid_from включается в интервал, конец valid_to не включается: событие 1 октября относится только к версии 734. NULL означает, что конец текущего интервала пока неизвестен. На практике можно использовать дату и время."], ["Связать факты с нужной версией", "При загрузке продажи находят версию покупателя, действовавшую в бизнес-время продажи, и сохраняют её суррогатный ключ в таблице фактов. Сентябрьская продажа ссылается на 501, октябрьская — на 734. Так сохраняется город на момент события. Соединение только по customer_id может найти несколько версий и удвоить показатели."], ["Какой тип выбрать?", "Тип 1 — когда история не нужна. Тип 2 — когда отчёт должен отражать состояние на момент события. Тип 6 — когда явно нужны и историческая, и текущая классификации. Разные атрибуты одного измерения могут использовать разные стратегии. Существуют также типы 0, 3 и другие; здесь рассматриваются три выбранных варианта."], ["Тип 6 · история и актуальная классификация", "Здесь используем определение Kimball: тип 6 добавляет атрибуты типа 1 к измерению типа 2. В каждой версии остаётся исторический город, а рядом хранится current_city. После переезда current_city меняется на Краков во всех версиях C208. Продажи можно группировать по историческому или текущему городу. Это гибко, но усложняет обновления и увеличивает объём данных; тип 6 не становится автоматически лучше типа 2."], ["Что проверять при реализации", "Для одной сущности нельзя допускать пересекающиеся интервалы и непредусмотренные дубликаты текущей версии. Закрытие старой версии и создание новой должны быть согласованными, повторный запуск — безопасным. Для опоздавших исправлений нужны отдельные правила. Периодические снимки видят только доступное на момент съёмки состояние: все изменения между запусками восстановить из них нельзя."], ["Связь со слоями", "Историю можно фиксировать и приводить к общему виду в Silver, а измерения для бизнеса публиковать в Gold. Расположение зависит от проекта. Medallion Architecture организует этапы подготовки, Slowly Changing Dimensions — изменения во времени. Далее проверим, полны ли полученные данные, насколько они свежие и готовы ли к публикации."]], ["Отправная точка для исторической отчётности", "Сначала определите, нужны ли прошлые значения атрибута. Если нужны — тип 2 часто подходит как отправная точка. Если достаточно актуального значения — полезен тип 1."]], ["Задача завершилась.<br><em>А отчёту можно верить?</em>", "Успешный запуск означает, что код отработал. Это ещё не доказывает, что все нужные записи поступили и отчёт готов к использованию.", "quality", [["Четыре вопроса перед публикацией", "Полнота: все ли ожидаемые записи поступили? Уникальность: не появились ли дубликаты при повторной загрузке? Целостность связей: существуют ли покупатели и товары, на которые ссылаются заказы? Свежесть: какой бизнес-период доступен и когда данные обновились? Проверки должны опираться на явные правила, а не на ощущение, что всё выглядит нормально."], ["Сверка с источником", "Сравнивают число записей и нужные суммы в источнике и приёмнике за одинаковый период, с одинаковыми фильтрами и границей времени. Разница может указывать на пропущенную загрузку, фильтр или известное преобразование. Совпадение количества само по себе не доказывает корректность: проверки комбинируют, неожиданные расхождения разбирают."], ["Если зависимость не готова", "Заказы загрузились, а платежи — нет. Отчёт, которому нужны оба набора, нельзя считать готовым только по успеху загрузки заказов. Оркестрация отслеживает зависимости, фиксирует сбой и уведомляет ответственных. Если уместно, последнюю проверенную версию отчёта оставляют доступной с явным предупреждением о свежести."], ["Восстановление без удвоения", "После исправления причины повторяют нужные шаги. Идемпотентность означает, что повтор той же операции даёт тот же ожидаемый результат, а не добавляет дубликаты. Backfill — повторная обработка прошлого периода, например после исправления формулы. Восстановленные данные проверяют до публикации."], ["Смысл, ответственность и доступ", "У набора данных должны быть ответственный, определения показателей и подходящие права доступа. Data lineage показывает происхождение и цепочку преобразований. При необходимости время бизнес-события хранят отдельно от времени загрузки: продажа может опоздать, а «загружено сегодня» не означает «продано сегодня»."], ["Что должен видеть читатель", "Показывайте покрытый период и время последнего успешного обновления. Делайте пропуски и устаревание заметными. Надёжная система помогает понять, когда ответ готов и когда нужно подождать. Далее свяжем эти обязанности с работой дата-инженеров."]], ["Понятное обещание", "«Все вчерашние продажи проверены и доступны к 08:00». Следите и за сроком доставки, и за проверками, которые стоят за этим обещанием."]], ["Работа за кулисами<br><em>надёжных данных.</em>", "Дата-инженеры строят и поддерживают системы, превращающие разрозненные данные в надёжные наборы для людей и приложений.", "engineer", [["Подключить и подготовить", "Разобраться в источниках, организовать доступ, построить загрузки и преобразования. Вместе с экспертами бизнеса спроектировать полезные модели данных."], ["Сделать качество наблюдаемым", "Проверять пропуски, дубликаты, некорректные значения и опоздания. Следить за свежестью и сбоями. Документировать происхождение данных и преобразования — это называют data lineage."], ["Поддерживать работу", "Разбирать инциденты, восстанавливать пропущенные данные, адаптироваться к изменениям источников и ускорять обработку. Управлять доступом и затратами по мере роста системы."], ["Пример: заказ пришёл дважды", "Повторная попытка доставила тот же заказ. Инженер задаёт стабильный ключ записи, проектирует повторяемую загрузку, проверяет уникальность и выясняет причину. Цель — не удвоить выручку из-за повторного запуска."]], ["Результат шире, чем код", "Полезному набору данных нужны понятный смысл, ответственный, ожидаемая свежесть и практический способ обнаружить и исправить проблему."]], ["Хорошим решениям нужна<br><em>надёжная основа.</em>", "Результат работы — не просто перемещение данных. Люди должны уметь их использовать, понимать и знать, когда они готовы.", "business", [["Один вопрос, полный путь", "Менеджер спрашивает, какие категории выросли за квартал. Система собирает заказы и возвраты, применяет классификацию товаров и правила расчёта выручки. Отчёт показывает результат и время обновления."], ["Взаимодействие ролей", "Разработчики создают операционную логику магазина. Дата-инженеры строят потоки данных и аналитическую основу. Аналитики исследуют вопросы и объясняют выводы. На практике обязанности пересекаются и различаются между командами."], ["Как выглядит успех", "Отчёты готовы в обещанное время. Определения показателей задокументированы. Доступ соответствует обязанностям. Сбои обнаруживаются, а данные можно восстановить. Так аналитика становится полезной для решений."]], ["Главная мысль", "Дата-инженеры делают путь от операционных записей до полезных надёжных данных повторяемым."]], ["Несколько терминов.<br><em>Больше понимания.</em>", "Справочник, к которому можно вернуться, если незнакомое сокращение мешает читать.", "glossary", [], null]]}};
const t=(en,ru)=>lang==='ru'?ru:en;let lang='en',current=0;
const links=[['AWS · Transactional and analytical workloads','https://docs.aws.amazon.com/whitepapers/latest/data-warehousing-on-aws/modern-analytics-and-data-warehousing-architecture.html'],['Microsoft · Star schema explained','https://learn.microsoft.com/en-us/power-bi/guidance/star-schema'],['Microsoft · Data warehouse architecture','https://learn.microsoft.com/en-us/azure/architecture/example-scenario/data/small-medium-data-warehouse']];
links.push(['Databricks · Medallion architecture','https://docs.databricks.com/aws/en/lakehouse/medallion'],['Microsoft · Data warehouse medallion architecture','https://learn.microsoft.com/azure/architecture/databases/architecture/dataops-mdw']);
links.push(['Databricks · What is a lakehouse?','https://answers.databricks.com/lakehouse']);
links.push(['Kimball Group · Type 2: Add a new row','https://www.kimballgroup.com/data-warehouse-business-intelligence-resources/kimball-techniques/dimensional-modeling-techniques/type-2/'],['Kimball Group · Slowly Changing Dimension techniques','https://www.kimballgroup.com/data-warehouse-business-intelligence-resources/kimball-techniques/dimensional-modeling-techniques/']);
function flow(items){return '<div class="flow">'+items.map((x,i)=>`${i?'<span class="arrow" aria-hidden="true">→</span>':''}<div class="flowbox"><b aria-hidden="true">${x[0]}</b>${x[1]}<small>${x[2]||''}</small></div>`).join('')+'</div>'}
function illustration(kind){let body='',label=t('The online store / an illustrative example','Интернет-магазин / учебный пример');
if(kind==='database'){body=flow([['▧',t('Customer','Покупатель'),t('Chooses a pair of shoes','Выбирает кроссовки')],['↗',t('Application','Приложение'),t('Places order #1042','Оформляет заказ №1042')],['▤',t('Database','База данных'),t('Remembers the purchase','Сохраняет покупку')]])+`<div class="data-table"><table><caption class="mini">${t('A simplified orders table','Упрощённая таблица заказов')}</caption><thead><tr><th>order_id</th><th>customer_id</th><th>total_eur</th><th>status</th></tr></thead><tbody><tr><td>1042</td><td>208</td><td>89.00</td><td>${t('paid','оплачен')}</td></tr><tr><td>1043</td><td>519</td><td>120.00</td><td>${t('pending','ожидается')}</td></tr></tbody></table></div>`;}
else if(kind==='compare'){body=`<div class="twocol"><div class="flowbox"><b>↯</b>Online Transaction Processing (OLTP)<small>${t('“Save this order.”','«Сохрани этот заказ».')}</small></div><div class="flowbox"><b>▥</b>Online Analytical Processing (OLAP)<small>${t('“Compare a year of sales.”','«Сравни продажи за год».')}</small></div></div>`;}
else if(kind==='quality'){label=t('Publish only after required dependencies and checks pass','Публикация после готовности зависимостей и проверок');body=flow([['▤',t('Orders + payments','Заказы + платежи'),t('Required inputs','Нужные источники')],['✓',t('Validate','Проверить'),t('Complete · unique · fresh','Полнота · уникальность · свежесть')],['▥',t('Publish','Опубликовать'),t('Or hold and alert','Или остановить и уведомить')]]);}else if(kind==='scd'){label=t('One customer / a change on 1 October 2026','Один покупатель / изменение 1 октября 2026');body=flow([['▤',t('Before · Warsaw','До · Варшава'),'customer_id = C208'],['→',t('Customer moves','Покупатель переезжает'),'2026-10-01'],['▤',t('After · Kraków','После · Краков'),'customer_id = C208']]);}else if(kind==='lakehouse'){label=t('Lakehouse / a simplified platform stack','Lakehouse / упрощённое устройство платформы');body=`<div class="lakehouse-stack"><div class="flowbox"><b>▥</b>${t('Analytics and other consumers','Аналитика и другие потребители')}<small>${t('Reports · exploration · machine learning','Отчёты · исследования · машинное обучение')}</small></div><div class="flowbox">${t('Processing engines + catalog','Вычислительные движки + каталог')}<small>${t('Queries, transformations, discovery and access','Запросы, преобразования, поиск данных и доступ')}</small></div><div class="flowbox">${t('Managed tables','Управляемые таблицы')}<small>Delta Lake / Apache Iceberg</small></div><div class="flowbox">${t('Data files on object storage','Файлы данных в объектном хранилище')}<small>${t('Orders · website events · other source data','Заказы · события сайта · другие исходные данные')}</small></div></div>`;}else if(kind==='medallion'){label=t('Medallion Architecture / increasing refinement','Medallion Architecture / постепенная подготовка');body=flow([['Ⅰ','Bronze',t('Raw source records','Исходные записи')],['Ⅱ','Silver',t('Cleaned + validated data','Очищенные и проверенные данные')],['Ⅲ','Gold',t('Business-ready models','Модели для бизнеса')]])+`<div class="note"><strong>${t('Same store, different stages','Один магазин, разные этапы')}</strong><p>${t('Incoming orders → consistent order lines → daily sales by category.','Поступившие заказы → согласованные позиции заказов → продажи по дням и категориям.')}</p></div>`;}else if(kind==='star'){body=`<div style="max-width:550px;margin:auto"><div class="flowbox" style="width:45%;margin:0 auto 0px">${t('Date dimension · month, year','Измерение даты · месяц, год')}</div><div style="text-align:center;color:#81965b;line-height:1.5" aria-hidden="true">│</div><div class="flow"><div class="flowbox">${t('Product dimension','Измерение товара')}<small>${t('Category, brand','Категория, бренд')}</small></div><span class="arrow">—</span><div class="flowbox" style="background:#dce8bc">${t('Sales facts','Факты продаж')}<small>${t('One row per order line','Строка = позиция заказа')}</small></div><span class="arrow">—</span><div class="flowbox">${t('Customer dimension','Измерение покупателя')}<small>${t('Region','Регион')}</small></div></div></div>`;label=t('Star schema / context around an event','Схема «звезда» / контекст события');}
else{const sets={transaction:[['▧',t('Reserve stock','Резерв товара')],['＋',t('Create order','Создание заказа')],['✓',t('Commit together','Общий commit'),t('Or roll back both','Или отмена обоих изменений')]],sources:[['▤',t('Application database','База приложения'),t('Online Transaction Processing (OLTP)','Online Transaction Processing (OLTP)')],['↻',t('Scheduled data job','Загрузка по расписанию'),t('Copy + prepare + check','Скопировать + подготовить + проверить')],['▥',t('Data warehouse','Хранилище данных'),t('Online Analytical Processing (OLAP)','Online Analytical Processing (OLAP)')]],warehouse:[['▤',t('Source systems','Источники')],['▦',t('Data warehouse','Хранилище'),t('History + shared definitions','История + общие определения')],['▥',t('Analysis','Анализ')]],pipeline:[['▤',t('Extract','Извлечение')],['↓',t('Load','Загрузка')],['⤨',t('Transform','Преобразование')],['▥',t('Report','Отчёт')]],engineer:[['⤨',t('Build','Построить')],['✓',t('Check','Проверить')],['◎',t('Monitor','Наблюдать')],['↻',t('Recover','Восстановить')]],business:[['▧',t('An order','Заказ')],['▦',t('Trusted data','Надёжные данные')],['▥',t('An answer','Ответ')],['↗',t('A decision','Решение')]]};body=flow(sets[kind]||sets.warehouse);if(kind==='pipeline')label=t('Extract, Load, Transform (ELT) / one possible pipeline','Extract, Load, Transform (ELT) / один из вариантов');}
return `<figure class="illustration" style="margin-left:0;margin-right:0"><div class="figuretitle">${label}</div>${body}<figcaption class="caption">${t('A simplified model. Every chapter follows the same store.','Упрощённая модель. Во всех главах — один и тот же магазин.')}</figcaption></figure>`;}
function comparison(){const rows=lang==='en'?[['Main job','Run business operations','Explore and summarize data'],['Typical query','Find one order','Aggregate many order lines'],['Changes','Frequent small writes','Loads and transformations'],['Data view','Often current operational state','Often integrated history'],['Typical users','Applications and operational teams','Analysts and decision-makers']]:[['Задача','Обслуживать операции','Исследовать и обобщать данные'],['Запрос','Найти один заказ','Агрегировать много позиций'],['Изменения','Частые небольшие записи','Загрузки и преобразования'],['Взгляд на данные','Часто текущее состояние','Часто объединённая история'],['Пользователи','Приложения и операционные команды','Аналитики и руководители']];return `<div class="tablewrap"><table><thead><tr><th>${t('Typical patterns','Типичные особенности')}</th><th>Online Transaction Processing (OLTP)</th><th>Online Analytical Processing (OLAP)</th></tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`;}
function glossary(){let terms=[['OLTP','Online Transaction Processing',t('Processing everyday operations, such as creating an order.','Обработка текущих операций, например создания заказа.')],['OLAP','Online Analytical Processing',t('Analyzing and aggregating data across many records.','Анализ и обобщение множества записей.')],['DWH','Data Warehouse',t('An integrated data system prepared for analytics.','Система объединённых данных для аналитики.')],['ETL','Extract, Transform, Load',t('Extract data, transform it, then load it.','Извлечь, преобразовать, затем загрузить.')],['ELT','Extract, Load, Transform',t('Extract and load data, then transform it.','Извлечь, загрузить, затем преобразовать.')],['CDC','Change Data Capture',t('Identifying changes in a source system.','Отслеживание изменений в источнике.')],['SQL','Structured Query Language',t('A language for querying and managing relational data.','Язык запросов и управления реляционными данными.')],['BI','Business Intelligence',t('Methods and tools for exploring business data and reporting.','Методы и инструменты анализа бизнес-данных и отчётности.')]];terms.push(...extraTerms());return `<dl class="terms">${terms.map(r=>`<dt>${r[0]}${r[1]?" — "+r[1]:""}</dt><dd>${r[2]}</dd>`).join('')}</dl><section class="section"><h2>${t('Sources & illustrations','Источники и иллюстрации')}</h2><p>${t('The diagrams in this draft are original, simplified teaching illustrations. These primary references provide deeper explanations and additional architecture diagrams. The Star Schema chapter also embeds an illustration from Microsoft Learn, credited alongside the image.','Схемы черновика созданы специально для объяснения материала. Ниже — первоисточники с подробными объяснениями и дополнительными архитектурными схемами. В главу о Star Schema также встроена иллюстрация Microsoft Learn с указанием источника.')}</p>${links.map(r=>`<p><a href="${r[1]}" target="_blank" rel="noopener">${r[0]} ↗</a></p>`).join('')}</section>`;}
function overnightIllustration(){return `<figure class="illustration overnight-minimal" style="margin-left:0;margin-right:0"><div class="figuretitle">${t('One overnight batch / an example schedule','Одна ночная загрузка / пример расписания')}</div>${flow([['▤',t('Monday · orders arrive','Понедельник · заказы'),t('Application database','База приложения')],['↻',t('Tuesday 02:00 · job runs','Вторник 02:00 · загрузка'),t('Copy → prepare → check','Копирование → подготовка → проверка')],['▥',t('08:00 · report ready','08:00 · отчёт готов'),t('Yesterday’s sales in the warehouse','Вчерашние продажи в хранилище')]])}<figcaption class="caption">${t('The application keeps running. The analytical copy is refreshed overnight. This schedule is an example, not a requirement.','Приложение продолжает работать. Аналитическая копия обновляется ночью. Это пример расписания, а не обязательное правило.')}</figcaption></figure>`;}
function scdTable(type){const table=(headers,rows)=>`<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;let content='';if(type===1){content=table(['customer_id','city'],[['C208','<s>Warsaw</s> → Kraków']]);}if(type===2){content=`<p class="mini">${t('Start with source columns: customer_id + city. Add a version key and validity columns:','Начинаем с колонок источника: customer_id + city. Добавляем ключ версии и период действия:')}</p>`+table(['customer_sk','customer_id','city','valid_from','valid_to','is_current'],[['501','C208','Warsaw','2026-01-01','2026-10-01','false'],['734','C208','Kraków','2026-10-01','NULL','true']])+`<p class="mini">${t('Example: this customer’s history starts on 1 January. Interval convention: valid_from ≤ event time < valid_to; an open end has no upper bound.','В примере история покупателя начинается 1 января. Правило интервала: valid_from ≤ время события < valid_to; открытый конец не ограничен сверху.')}</p>`;}if(type===6){content=table(['customer_sk','customer_id','historical_city','current_city'],[['501','C208','Warsaw','Kraków'],['734','C208','Kraków','Kraków']])+`<p class="mini">${t('The Type 2 validity columns remain; omitted here for readability.','Колонки периода действия типа 2 сохраняются; здесь они опущены для читаемости.')}</p>`;}return `<figure class="illustration" style="margin-left:0;margin-right:0"><div class="figuretitle">${t('Type','Тип')} ${type} · ${t('illustrative customer dimension','учебный пример измерения покупателей')}</div>${content}</figure>`;}
function starReferenceFigure(){return `<figure class="illustration" style="margin-left:0;margin-right:0"><div class="figuretitle">Star Schema · ${t('one fact table, surrounding dimensions','таблица фактов и окружающие измерения')}</div><a href="https://learn.microsoft.com/en-us/power-bi/guidance/media/star-schema/star-schema-example-2.svg" target="_blank" rel="noopener"><img src="https://learn.microsoft.com/en-us/power-bi/guidance/media/star-schema/star-schema-example-2.svg" style="display:block;width:100%;max-width:680px;height:auto;margin:0 auto;background:white;padding:20px;border-radius:6px" alt="${t('Star schema: a central fact table connects directly to surrounding dimension tables.','Схема звезда: центральная таблица фактов напрямую связана с окружающими таблицами измерений.')}"></a><figcaption class="caption">${t('The fact table sits at the center; each surrounding dimension connects directly to it. Unlike a Snowflake Schema, dimension hierarchies do not branch into additional tables here.','Таблица фактов находится в центре, каждое измерение связано с ней напрямую. В отличие от снежинки, иерархии измерений здесь не разветвляются на дополнительные таблицы.')}<br>${t('Source','Источник')}: <a href="https://learn.microsoft.com/en-us/power-bi/guidance/star-schema" target="_blank" rel="noopener">Microsoft Learn · Understand star schema ↗</a></figcaption></figure>`;}
function schemaOverview(){const rows=lang==='en'?[['Star','Fact + direct dimensions','A clear reporting model'],['Snowflake','Fact + normalized dimension hierarchies','Manage hierarchies separately'],['Fact Constellation','Multiple facts + shared dimensions','Analyze related processes consistently'],['Wide table','Event measures + repeated attributes','Serve a focused query workload']]:[['Звезда','Факт + прямые измерения','Понятная модель отчётности'],['Снежинка','Факт + нормализованные иерархии','Отдельное управление иерархиями'],['Созвездие','Несколько фактов + общие измерения','Согласованный анализ процессов'],['Широкая таблица','Меры события + повтор атрибутов','Конкретная аналитическая нагрузка']];return `<div class="tablewrap"><table><thead><tr><th>${t('Pattern','Вариант')}</th><th>${t('Shape','Устройство')}</th><th>${t('Typical motivation','Зачем используют')}</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function snowflakeFigure(){return `<figure class="illustration overnight-minimal" style="margin-left:0;margin-right:0"><div class="figuretitle">Snowflake Schema · ${t('a normalized product hierarchy','нормализованная иерархия товаров')}</div>${flow([['▥',t('Sales facts','Факты продаж'),'product_key'],['▤',t('Product','Товар'),'product_key · subcategory_key'],['▤',t('Subcategory','Подкатегория'),'subcategory_key · category_key'],['▤',t('Category','Категория'),'category_key · category_name']])}<figcaption class="caption">${t('Each sale references one product; products reference their subcategory, which references its category. Customer and Date dimensions are omitted here. In a Star Schema, these category attributes can live in the Product dimension itself.','Продажа ссылается на товар, товар — на подкатегорию, подкатегория — на категорию. Измерения покупателей и дат здесь опущены. В звезде атрибуты категорий могут находиться прямо в измерении товаров.')}</figcaption></figure>`;}
function teachingTable(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function transformationTable(){return teachingTable([t('Step','Шаг'),t('Before','До'),t('After','После')],lang==='en'?[['Deduplicate','Order 1042 delivered twice','One intended order record'],['Standardize','paid / PAID / Paid','paid'],['Convert types','A date received as text','A typed date value'],['Join','Order 1042 + payment for 1042','Order with its payment status'],['Aggregate','Order lines: €50 + €39','Daily sales: €89 (illustrative)']]:[['Дедупликация','Заказ 1042 доставлен дважды','Одна ожидаемая запись заказа'],['Стандартизация','paid / PAID / Paid','paid'],['Преобразование типов','Дата поступила текстом','Значение типа дата'],['Соединение','Заказ 1042 + платёж за 1042','Заказ со статусом оплаты'],['Агрегирование','Позиции: €50 + €39','Продажи за день: €89 (пример)']]);}
function grainTable(){return `<figure class="illustration" style="margin-left:0;margin-right:0"><div class="figuretitle">${t('Grain / one row means one order line','Детализация / строка означает одну позицию заказа')}</div>${teachingTable(['order_id','line_id',t('Product','Товар'),t('Amount','Сумма')],[['1042','1',t('Shoes','Кроссовки'),'€50'],['1042','2',t('Socks','Носки'),'€9'],['1042','3',t('Bag','Сумка'),'€30']])}<figcaption class="caption">${t('3 rows · 1 distinct order · €89 total. Counting rows would give 3 order lines, not 3 orders.','3 строки · 1 уникальный заказ · сумма €89. Подсчёт строк даёт 3 позиции заказа, а не 3 заказа.')}</figcaption></figure>`;}
function extraTerms(){return [
['Schema','',t('Can mean a table structure, a named namespace containing database objects, or a model layout such as Star Schema. The context matters.','Может означать структуру таблицы, именованное пространство объектов базы или устройство модели, например звезду. Смысл зависит от контекста.')],
['Metadata','',t('Information about data: column types, source, owner or ingestion time.','Информация о данных: типы колонок, источник, ответственный или время загрузки.')],
['Business key','',t('An identifier of an entity in the business or source, such as customer_id.','Идентификатор сущности в бизнесе или источнике, например customer_id.')],
['Surrogate key','',t('An identifier assigned in the analytical model, for example to distinguish versions of a customer.','Ключ, назначенный в аналитической модели, например для различения версий покупателя.')],
['Grain','',t('The precise meaning of one row, such as one order line or one product per day.','Точный смысл одной строки: например, позиция заказа или товар за день.')],
['Data mart','',t('A focused collection prepared for a subject or team.','Набор данных, подготовленный под тему или команду.')],
['Data lineage','',t('The origin of a dataset and the transformations and dependencies that produced it.','Происхождение набора данных, его преобразования и зависимости.')],
['Join','',t('Connecting related records from tables using matching keys or conditions.','Соединение связанных записей таблиц по ключам или условиям.')],
['Aggregation','',t('Grouping detailed records into measures, such as daily sales totals.','Обобщение подробных записей в показатели, например продажи за день.')],
['Orchestration','',t('Coordinating task schedules, dependencies, retries and execution status.','Управление расписанием, зависимостями, повторами и состоянием задач.')],
['Idempotency','',t('Repeating the same operation preserves the intended result rather than adding duplicate effects.','Повтор одной операции сохраняет ожидаемый результат, не добавляя дублирующих эффектов.')],
['Backfill','',t('Processing a historical period again to fill gaps or apply corrected logic.','Повторная обработка прошлого периода для заполнения пропусков или применения исправленной логики.')],
['Object storage','',t('Storage that keeps data as named objects, commonly used for files in a data lake.','Хранение данных как именованных объектов, часто используемое для файлов озера данных.')],
['NULL','',t('A marker for a missing or unknown value; not the same as zero or an empty string.','Признак отсутствующего или неизвестного значения; не равен нулю или пустой строке.')]
];}

function render(){let parts=location.hash.slice(1).split('/');lang=parts[0]==='ru'?'ru':'en';current=Math.max(0,ids.indexOf(parts[1]||ids[0]));const d=data[lang],p=d.pages[current];document.documentElement.lang=lang;document.title=d.titles[current]+' — Data Engineering';document.getElementById('navlabel').textContent=d.contents;document.getElementById('draft').textContent=d.draft;document.getElementById('asidecopy').textContent=d.aside;document.getElementById('nav').innerHTML=d.titles.map((title,i)=>`<a href="#${lang}/${ids[i]}" ${i===current?'class="active" aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${title}</a>`).join('');document.getElementById('breadcrumb').textContent='Field guide / '+d.titles[current];['en','ru'].forEach(l=>{let b=document.getElementById(l);b.classList.toggle('active',lang===l);b.setAttribute('aria-pressed',String(lang===l));});let sections=p[3].map((x,i)=>`${ids[current]==='why-warehouse'&&i===4?overnightIllustration():''}${ids[current]==='scd'&&i===6?`<details class="further"><summary>${t('Optional: hybrid Type 6 and implementation details','Дополнительно: гибридный тип 6 и детали реализации')}</summary>`:''}<section class="section"><h2>${x[0]}</h2><p>${x[1]}</p>${ids[current]==='pipelines'&&i===1?transformationTable():''}${ids[current]==='modeling'&&i===0?grainTable():''}${ids[current]==='modeling'&&i===1?schemaOverview():''}${ids[current]==='modeling'&&i===2?starReferenceFigure():''}${ids[current]==='modeling'&&i===4?snowflakeFigure():''}${ids[current]==='scd'&&[1,2,6].includes(i)?scdTable(i===1?1:i===2?2:6):''}</section>${ids[current]==='scd'&&i===7?'</details>':''}`).join('');let sourceIndex=ids[current]==='quality'?-1:ids[current]==='scd'?6:ids[current]==='lakehouse'?5:ids[current]==='medallion'?3:ids[current]==='modeling'?1:current===0||current===2?-1:ids[current]==='pipelines'?2:0;
document.getElementById('main').innerHTML=`<div class="eyebrow"><span class="tag">${d.chapter} ${String(current+1).padStart(2,'0')}</span><span>${ids[current]==='glossary'?t('KEEP THIS HANDY','ПОД РУКОЙ'):t('THE FOUNDATIONS','ОСНОВЫ')}</span></div><h1>${p[0]}</h1><p class="lead">${p[1]}</p><div class="reading"><span>◷ ${ids[current]==='glossary'?'3':'4'} ${d.read}</span><span>${d.example}</span></div>${ids[current]==='glossary'?glossary():illustration(p[2])+sections+(current===1?comparison():'')+(p[4]?`<div class="note"><strong>${p[4][0]}</strong><p>${p[4][1]}</p></div>`:'')+(sourceIndex>=0?`<div class="source">${d.sources}: <a href="${links[sourceIndex][1]}" target="_blank" rel="noopener">${links[sourceIndex][0]} ↗</a></div>`:'')}<div class="pager">${current>0?`<a href="#${lang}/${ids[current-1]}"><small>← ${d.previous}</small>${d.titles[current-1]}</a>`:''}${current<ids.length-1?`<a href="#${lang}/${ids[current+1]}"><small>${d.next} →</small>${d.titles[current+1]}</a>`:''}</div>`;document.body.classList.remove('menuopen');window.scrollTo(0,0);}
window.addEventListener('hashchange',render);document.getElementById('en').onclick=()=>location.hash='en/'+ids[current];document.getElementById('ru').onclick=()=>location.hash='ru/'+ids[current];document.getElementById('menu').onclick=()=>document.body.classList.toggle('menuopen');document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('menuopen')});render();
